function uuid() { return typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`; }
export function timeMinutes(time: string): number { const match = /^(\d{2}):(\d{2})$/.exec(time); if (!match || +match[1] > 23 || +match[2] > 59) return NaN; return +match[1] * 60 + +match[2]; }
function formatTime(minutes: number) { return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`; }
export function isISODate(value: string): boolean { if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false; const d = new Date(`${value}T12:00:00Z`); return Number.isFinite(d.getTime()) && d.toISOString().slice(0, 10) === value; }
function todayISO() { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Africa/Casablanca", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date()); return ["year", "month", "day"].map(k => parts.find(p => p.type === k)?.value).join("-"); }
export function addDays(date: string, count: number) { const d = new Date(`${date}T12:00:00Z`); d.setUTCDate(d.getUTCDate() + count); return d.toISOString().slice(0, 10); }
export function mondayOf(date: string) { return addDays(date, -((new Date(`${date}T12:00:00Z`).getUTCDay() + 6) % 7)); }
function displayDate(date: string, lang: ScheduleLanguage, options: Intl.DateTimeFormatOptions = { day: "numeric", month: "short" }) { return new Intl.DateTimeFormat(lang === "ar" ? "ar-MA" : lang === "en" ? "en-GB" : "fr-FR", { ...options, timeZone: "UTC" }).format(new Date(`${date}T12:00:00Z`)); }
function validTimeRange(start: string, end: string) { const a = timeMinutes(start), b = timeMinutes(end); return Number.isInteger(a) && Number.isInteger(b) && a >= START && b <= END && b - a >= 30 && b - a <= 240 && a % 15 === 0 && b % 15 === 0; }
export function findSessionConflict(sessions: ScheduledSession[], candidate: Pick<ScheduledSession, "id" | "date" | "start" | "end">) { return sessions.find(s => s.id !== candidate.id && s.date === candidate.date && timeMinutes(s.start) < timeMinutes(candidate.end) && timeMinutes(candidate.start) < timeMinutes(s.end)); }
function safeURL(value: string): string | null { try { const url = new URL(value.trim()); return ["http:", "https:"].includes(url.protocol) && !url.username && !url.password ? url.href : null; } catch { return null; } }
const record = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const str = (v: unknown, max: number): v is string => typeof v === "string" && v.length <= max;
export function isScheduleData(value: unknown): value is ScheduleData {
  if (!record(value) || value.version !== 1 || !Array.isArray(value.classes) || !Array.isArray(value.sessions) || value.classes.length > 50 || value.sessions.length > 2000) return false;
  const ids = new Set<string>(), colors = new Set<string>(), names = new Set<string>();
  for (const c of value.classes) {
    if (!record(c) || !str(c.id, 150) || !c.id || ids.has(c.id) || !str(c.name, 80) || !c.name.trim() || names.has(c.name.trim().toLocaleLowerCase()) || !str(c.room, 80) || !c.room.trim() || !str(c.color, 7) || !/^#[0-9a-f]{6}$/i.test(c.color) || colors.has(c.color.toLowerCase()) || !["svt", "pc", "math", "arabic", "french"].includes(String(c.subject)) || !["primary", "middle", "high"].includes(String(c.schoolLevel))) return false;
    ids.add(c.id); colors.add(c.color.toLowerCase()); names.add(c.name.trim().toLocaleLowerCase());
  }
  const sessionIds = new Set<string>();
  for (const s of value.sessions) {
    if (!record(s) || !str(s.id, 150) || !s.id || sessionIds.has(s.id) || !str(s.classId, 150) || !ids.has(s.classId) || !str(s.date, 10) || !isISODate(s.date) || new Date(`${s.date}T12:00:00Z`).getUTCDay() === 0 || !str(s.start, 5) || !str(s.end, 5) || !validTimeRange(s.start, s.end) || !str(s.title, 240) || !s.title.trim() || !str(s.competency, 2000) || !str(s.notes, 12000) || !["planned", "in_progress", "completed"].includes(String(s.status)) || !Array.isArray(s.resources) || s.resources.length > 12) return false;
    const resourceIds = new Set<string>();
    for (const r of s.resources) { if (!record(r) || !str(r.id, 150) || !r.id || resourceIds.has(r.id) || !str(r.title, 120) || !r.title.trim() || !str(r.url, 2048) || !safeURL(r.url)) return false; resourceIds.add(r.id); }
    sessionIds.add(s.id);
  }
  const ordered = [...value.sessions].sort((a, b) => String(a.date).localeCompare(String(b.date)) || timeMinutes(a.start) - timeMinutes(b.start));
  return ordered.every((s, i) => i === 0 || s.date !== ordered[i - 1].date || timeMinutes(s.start) >= timeMinutes(ordered[i - 1].end));
}
